mapper.update:
UPDATE saving_group sg
JOIN `groups` g ON g.group_id = sg.group_id
SET sg.status = #{status}
WHERE sg.group_id = #{groupId}
AND g.deleted_at IS NULL

mapper.select:
SELECT group_id, COUNT(DISTINCT member_id) AS member_count FROM group_member WHERE membership_status = 'APPROVED' AND group_id IN
#{groupId}
GROUP BY group_id
